  const color1: string = '#65ff00dd'
  const color2: string = '#6500ff99'
  const color3: string = '#65ffe600'
  const color4: string = '#6595ff00'
  const color5: string = '#65000dff'
  const color6: string = '#650099ff'
  const colorArray: Array<string> = [color1, color2, color3, color4, color5, color6]

  RelativeContainer() {
    Row() {
      Rect()
        .height(25)
        .width(item * 600 / max)
        .foregroundColor(colorArray[index])
        .radius(5)
        .align(Alignment.Start)
      Text(' ' + item)
        .fontSize(17)
    }
  }.height(28)
}

@Builder
function buildDataPanel(config: DataPanelConfiguration) {
  Column() {
    Column() {
      ForEach(config.values, (item: number, index: number) => {
        ChildItemBuilder(item, index, config.maxValue)
      }, (item: string) => item)
    }.padding(10)

    Column() {
      Line().width('100%').backgroundColor('#ff373737').margin({ bottom: 5 })
    }.padding({ left: 20, right: 20 })

    Row() {
      Text('Length=' + config.values.length + '    ').margin({ left: 10 }).align(Alignment.Start)
      Text('Max=' + config.maxValue).margin({ left: 10 }).align(Alignment.Start)
    }
  }
}

class DataPanelBuilder implements ContentModifier<DataPanelConfiguration> {
  constructor() {
  }

  applyContent(): WrappedBuilder<[DataPanelConfiguration]> {
    return wrapBuilder(buildDataPanel)
  }
}

