    if (this.enableEmail) {
      types.push(TextDataDetectorType.EMAIL)
    }
    if (this.enableDate) {
      types.push(TextDataDetectorType.DATE_TIME)
    }
    return types
  }

  public updateConfig() {
    this.config = { types: this.getTypes() }
  }

