    instance
      .enableSelectedDataDetector(this.enableSelectedDataDetector)
      .selectedDataDetectorConfig(this.config)
  }
}

class Pair<T, U> {
  public name: T;
  public value: U;

  constructor(name: T, value: U) {
    this.name = name;
    this.value = value;
  }

  toString(): string {
    return `Pair(${this.name}, ${this.value})`;
  }
}

