struct WaterFlowSectionDemo26 {
  minSize: number = 80
  maxSize: number = 180
  fontSize: number = 24
  @State colors: number[] = [0xFFC0CB, 0xDA70D6, 0x6B8E23, 0x6A5ACD, 0x00FFFF, 0x00FF7F]
  columns: string = '1fr'
  scroller: Scroller = new Scroller()
  dataCount: number = 7
  dataSource: WaterFlowDataSource = new WaterFlowDataSource(this.dataCount)
  @State sections: WaterFlowSections = new WaterFlowSections()

  twoColumnSection: SectionOptions = {
    itemsCount: 5,
    crossCount: 3,
    columnsGap: 0,
    rowsGap: 0,
    margin: 0,
    onGetItemMainSizeByIndex: (index: number) => {
      return 80
    }
  }
  lastSection: SectionOptions = {
    itemsCount: 3,
    crossCount: 1,
    onGetItemMainSizeByIndex: (index: number) => {
      return 100
    }
  }

  aboutToAppear() {
    let sectionOptions: SectionOptions[] = []
    let count = 0
    while (count < this.dataCount) {
      sectionOptions.push(this.twoColumnSection)
      this.lastSection.itemsCount = this.dataCount - this.twoColumnSection.itemsCount
      sectionOptions.push(this.lastSection)
      break;
    }
    this.sections.splice(0, 0, sectionOptions)
  }

  build() {
    Column({ space: 2 }) {
      WaterFlow({ scroller: this.scroller, sections: this.sections }) {
        LazyForEach(this.dataSource, (item: number) => {
          FlowItem() {
            ReusableFlowItem26({ item: item })
          }
          .key(`WaterFlowSectionDemo26_${item}`)
          .width('100%')
          .height(100)
          .backgroundColor(this.colors[item % 5])
        }, (item: string) => item).cachedCount(4)
      }
      .columnsTemplate('1fr')
      .columnsGap(10)
      .rowsGap(10)
      .backgroundColor(0xFAEEE0)
      .width(300)
      .height('100%')
      .layoutWeight(1)

    }.margin({top:'10%',left:'10%'})
  }
}

