      .height('30vp')
      .backgroundColor(Color.Grey)
      .opacity(0.4)
      .onClick(() => {
        this.doSomething()
      })
    } else {
      Button({ stateEffect: this.isOk }) {
        Image($r('app.media.ic_public_pass'))
          .width('20vp')
          .height('20vp')
      }
      .margin({ bottom: '20vp' })
      .width('30%')
      .height('30vp')
      .backgroundColor(Color.Grey)
      .onClick(() => {
        router.back({
          url: 'pages/ArkUI/ArkUI_index',
          params: {
            result: 'true ', title: this.name,
          }
        })
        promptAction.showToast({
          message: '通过', duration: 1000
        });
      })
    }
  }

  @Builder
  FailBtn(text: Resource, isFullScreen: boolean) {
    Button() {
      Image($r('app.media.ic_public_fail'))
        .width('20vp')
        .height('20vp')
    }
    .margin({ bottom: '20vp' })
    .width('30%')
    .height('30vp')
    .backgroundColor(Color.Grey)
    .onClick(() => {
      router.back({
        url: 'pages/ArkUI/ArkUI_index',
        params: {
          result: 'false', title: this.name,
        }
      })
      promptAction.showToast({
        message: '失败', duration: 1000
      });
    })
  }

  build() {
    Column({ space: 10 }) {
      Row() {
        Button() {
          Image($r('app.media.ic_public_back'))
            .width('20vp')
            .height('18vp')
            .margin({ left: '20vp' })
        }
        .backgroundColor(Color.Black)
        .size({ width: '40vp', height: '30vp' })
        .onClick(() => {
          router.back({
            url: 'pages/ArkUI/ArkUI_index',
            params: { result: 'None' }
          })
        })

        Text(this.name)
          .fontColor(Color.White)
          .fontSize('18fp')
          .margin({ left: '-20vp' })
        Text('hello')
          .fontColor(Color.White)
          .visibility(Visibility.Hidden)
      }
      .backgroundColor(Color.Black)
      .height('10%')
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween)
      Row({ space: 10 }) {
        Text(`是否设备支持屏幕朗读`).fontColor(Color.Green).fontSize('18fp').margin({ top: 20 })
      }
      Row({ space: 10 }) {
        Column() {
          Button(`不支持`)
            .borderRadius(8)
            .backgroundColor(0x317aff)
            .width('30%')
            .enabled(!this.yesEnable)
            .opacity(!this.yesEnable ? 1 : 0.4)
            .onClick(async () => {
              this.doSomething()
            })
        }

        Column() {
          Button(`支持`)
            .borderRadius(8)
            .backgroundColor(0x317aff)
            .width('30%')
            .onClick(async () => {
              this.yesEnable = true;
              this.onAccessibilityHoverEnable = true;
            })
        }
      }

      Column({ space: 10 }) {
        Text('slider 设置刻度点播报内容').fontSize(15).fontColor(0xCCCCCC).width('90%').margin(15)
        Text(JSON.stringify(this.checkList))
        Row(){
          Slider({
            value: this.outSetValueOne,
            min: 0,
            max: 5,
            style: SliderStyle.InSet
          })
            .showSteps(true, { stepsAccessibility: this.currentOptionMap })
            .width('85%')
            .onChange((value: number) => {
              this.checkList = this.checkList.filter(item => item !== value);
              this.outSetValueOne = value;
            })
        }
        Button('检查所有点是否都点过:' + this.isCheck1)
          .onClick(() => {
            if (this.checkList.length === 0) {
              this.isCheck1 = true;
            }
          })
        Button('重新校验')
          .onClick(() => {
            this.checkList = [0, 1, 2, 3, 4, 5];
          })
        Text('modifier-slider 设置刻度点播报内容')
          .fontSize(15).fontColor(0xCCCCCC).width('90%').margin(15);
        Row() {
          Slider({
            value: this.outSetValueTwo,
            min: 0,
            max: 5,
            style: SliderStyle.InSet,
          })
            .attributeModifier(this.slider)
            .width('85%')
            .onChange((value: number) => {
              this.checkList = this.checkList.filter(item => item !== value);
              this.outSetValueTwo = value;
            })
        }
        Button('检查所有点是否都点过:' + this.isCheck2)
          .onClick(() => {
            if (this.checkList.length === 0) {
              this.isCheck2 = true;
            }
          })
      }
      .height('60%')
      .backgroundColor('#F1F3F5')
      Row() {
        this.PassBtn($r('app.string.btn_fullscreen'), true);
        Button() {
          Image($r('app.media.ic_public_help'))
            .width('20vp')
            .height('20vp')
        }
        .margin({ bottom: '20vp' })
        .width('30%')
        .height('30vp')
        .backgroundColor(Color.Grey)
        .onClick(() => {
          AlertDialog.show(
            {
              title: '操作提示',
              message: this.stepTips,
              confirm: {
                value: 'OK',
                action: () => {
                }
              }
            }
          )
        })
        this.FailBtn($r('app.string.btn_fullscreen'), true);
      }
      .height('10%')
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .backgroundColor(Color.Black)
    }.width('100%')
  }
}

